export function deepClone<T>(value: T): T {
  return cloneInternal(value, new WeakMap()) as T;
}

function cloneInternal(value: unknown, seen: WeakMap<object, unknown>): unknown {
  if (value === null || typeof value !== 'object') {
    return value;
  }

  if (seen.has(value as object)) {
    return seen.get(value as object);
  }

  if (value instanceof Date) {
    const clonedDate = new Date(value.getTime());
    seen.set(value, clonedDate);
    return clonedDate;
  }

  if (Array.isArray(value)) {
    const result: unknown[] = [];
    seen.set(value, result);
    for (const item of value) {
      result.push(cloneInternal(item, seen));
    }
    return result;
  }

  const result: Record<string, unknown> = {};
  seen.set(value, result);
  for (const key of Object.keys(value as Record<string, unknown>)) {
    result[key] = cloneInternal((value as Record<string, unknown>)[key], seen);
  }

  return result;
}

/**
 * Deep equality check for two values.
 */
export function deepEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (typeof a !== typeof b) return false;

  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
